import { Form, Input, Button, Stack } from '@design-schema/react';

const fields = (
  <Stack gap="normal">
    <Input label="Email address" name="email" type="email" required autocomplete="email" />
    <Input
      label="Password"
      name="password"
      type="password"
      required
      autocomplete="current-password"
      description="At least 8 characters."
    />
  </Stack>
);

const actions = (
  <Stack direction="horizontal" gap="tight" align="start">
    <Button label="Sign in" type="submit" />
    <Button label="Cancel" variant="secondary" />
  </Stack>
);

<Form name="sign-in" label="Sign in" actions={actions}>{fields}</Form>

